// node --test .github/scripts/tidy-footers.test.mjs
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { withoutFooter } from "./tidy-footers.mjs";

const LINK = "https://claude.ai/code/session_0123456789";

describe("the footer", () => {
  it("comes off a description, with the line above it", () => {
    const body = `The problem.\n\n## Tested\n\n- All pass.\n\n---\n\n_Generated by [Claude Code](${LINK})_\n`;
    assert.equal(withoutFooter(body), "The problem.\n\n## Tested\n\n- All pass.\n");
  });

  it("comes off a comment without a line, and in its other wordings", () => {
    assert.equal(withoutFooter(`Thanks for reporting this!\n\n_Generated by [Claude Code](${LINK})_`), "Thanks for reporting this!\n");
    assert.equal(withoutFooter(`Fixed.\n\n🤖 Generated with [Claude Code](${LINK})\n\n`), "Fixed.\n");
  });

  it("leaves the rest alone, horizontal rules too", () => {
    assert.equal(withoutFooter("Before.\n\n---\n\nAfter, made with [Claude Code](https://claude.com).\n"), null);
    assert.equal(withoutFooter("_Generated by [Claude Code](x)_ is what it said, before the end.\n"), null);
    assert.equal(withoutFooter(`Quoted:\n\n_Generated by [Claude Code](${LINK})_\n\nand then more.\n`), null);
    assert.equal(withoutFooter(""), null);
  });
});
